1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"context"
6		"database/sql"
7		"errors"
8		"fmt"
9		"strings"
10	
11		"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
12		_ "modernc.org/sqlite"
13	)
14	
15	// Store wraps the SQLite handle so callers never touch database/sql directly.
16	type Store struct {
17		db *sql.DB
18	}
19	
20	// Open prepares the database file and the schema this service needs.
21	func Open(path string) (*Store, error) {
22		return open(path, "sqlite")
23	}
24	
25	// open is Open with an injectable driver name, which lets the package tests
26	// register a driver wrapper around the real SQLite driver.
27	func open(path, driverName string) (*Store, error) {
28		dsn := path
29		if strings.Contains(dsn, "?") {
30			dsn += "&"
31		} else {
32			dsn += "?"
33		}
34		// foreign_keys must be enabled per connection; busy_timeout lets a
35		// concurrent writer wait for an open write transaction instead of
36		// failing immediately with SQLITE_BUSY.
37		dsn += "_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)"
38	
39		db, err := sql.Open(driverName, dsn)
40		if err != nil {
41			return nil, fmt.Errorf("open sqlite: %w", err)
42		}
43		if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
44			db.Close()
45			return nil, fmt.Errorf("enable wal: %w", err)
46		}
47		if _, err := db.Exec(schema); err != nil {
48			db.Close()
49			return nil, fmt.Errorf("apply schema: %w", err)
50		}
51		return &Store{db: db}, nil
52	}
53	
54	// Ping reports whether the storage layer is usable.
55	func (s *Store) Ping() error { return s.db.Ping() }
56	
57	// Close releases the database handle.
58	func (s *Store) Close() error { return s.db.Close() }
59	
60	// queryer is satisfied by *sql.DB, *sql.Tx and *sql.Conn.
61	type queryer interface {
62		ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
63		QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
64		QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
65	}
66	
67	// Register persists a normalized SBOM in a single write transaction. When the
68	// same artifact and version already hold an identical manifest, the existing
69	// record (with its original ID) is returned and created is false. Different
70	// content leaves the existing record untouched and returns model.ErrConflict.
71	func (s *Store) Register(ctx context.Context, in *model.SBOM) (sbom *model.SBOM, created bool, err error) {
72		c, err := s.db.Conn(ctx)
73		if err != nil {
74			return nil, false, unavailable(err)
75		}
76		defer c.Close()
77	
78		// BEGIN IMMEDIATE takes the writer lock up front, so two concurrent
79		// registrations for the same artifact/version serialize and the loser
80		// re-reads the winner's committed row instead of hitting the unique
81		// constraint.
82		if _, err := c.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
83			return nil, false, unavailable(err)
84		}
85		committed := false
86		defer func() {
87			if !committed {
88				// Best-effort cleanup; the original error is what callers need.
89				_, _ = c.ExecContext(context.Background(), "ROLLBACK")
90			}
91		}()
92	
93		var existingID int64
94		switch err := c.QueryRowContext(ctx,
95			"SELECT id FROM sboms WHERE artifact = ? AND version = ?",
96			in.Artifact, in.Version,
97		).Scan(&existingID); {
98		case err == nil:
99			existing, err := loadSBOM(ctx, c, existingID)
100			if err != nil {
101				return nil, false, err
102			}
103			if !equalContent(existing, in) {
104				return nil, false, model.ErrConflict
105			}
106			return existing, false, nil
107		case errors.Is(err, sql.ErrNoRows):
108			// Continue and insert.
109		default:
110			return nil, false, unavailable(err)
111		}
112	
113		res, err := c.ExecContext(ctx,
114			"INSERT INTO sboms (artifact, version) VALUES (?, ?)",
115			in.Artifact, in.Version)
116		if err != nil {
117			return nil, false, unavailable(err)
118		}
119		id, err := res.LastInsertId()
120		if err != nil {
121			return nil, false, unavailable(err)
122		}
123	
124		componentID := make(map[string]int64, len(in.Components))
125		insertComponent, err := c.PrepareContext(ctx,
126			"INSERT INTO components (sbom_id, coordinate, license) VALUES (?, ?, ?)")
127		if err != nil {
128			return nil, false, unavailable(err)
129		}
130		defer insertComponent.Close()
131		for i := range in.Components {
132			comp := &in.Components[i]
133			res, err := insertComponent.ExecContext(ctx, id, comp.Coordinate, comp.License)
134			if err != nil {
135				return nil, false, unavailable(err)
136			}
137			compID, err := res.LastInsertId()
138			if err != nil {
139				return nil, false, unavailable(err)
140			}
141			componentID[comp.Coordinate] = compID
142		}
143	
144		if depCount := countDependencies(in); depCount > 0 {
145			insertDep, err := c.PrepareContext(ctx,
146				"INSERT INTO dependencies (component_id, target_id) VALUES (?, ?)")
147			if err != nil {
148				return nil, false, unavailable(err)
149			}
150			defer insertDep.Close()
151			for i := range in.Components {
152				comp := &in.Components[i]
153				for _, dep := range comp.Dependencies {
154					if _, err := insertDep.ExecContext(ctx, componentID[comp.Coordinate], componentID[dep]); err != nil {
155						return nil, false, unavailable(err)
156					}
157				}
158			}
159		}
160	
161		if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
162			return nil, false, unavailable(err)
163		}
164		committed = true
165	
166		out := *in
167		out.ID = id
168		return &out, true, nil
169	}
170	
171	// List returns one page of complete SBOMs for an artifact ordered by ID, plus
172	// the total number of matching manifests. The count, the page manifests and
173	// the components/dependencies of that page are each read in one batched query
174	// (four SELECTs at most, regardless of page size) inside one transaction, so
175	// the total and the details share one committed snapshot and detail rows are
176	// never fetched for other pages or other artifacts. The detail reads go
177	// through the same loadComponentsInto/loadDependenciesInto loaders that
178	// Register's idempotency check uses, keeping one reconstruction rule.
179	func (s *Store) List(ctx context.Context, artifact string, page, pageSize int) (items []*model.SBOM, total int, err error) {
180		c, err := s.db.Conn(ctx)
181		if err != nil {
182			return nil, 0, unavailable(err)
183		}
184		defer c.Close()
185	
186		// A read transaction pins one snapshot for every SELECT below.
187		if _, err := c.ExecContext(ctx, "BEGIN"); err != nil {
188			return nil, 0, unavailable(err)
189		}
190		committed := false
191		defer func() {
192			if !committed {
193				// Best-effort cleanup; the original error is what callers need.
194				_, _ = c.ExecContext(context.Background(), "ROLLBACK")
195			}
196		}()
197	
198		if err := c.QueryRowContext(ctx,
199			"SELECT COUNT(*) FROM sboms WHERE artifact = ?", artifact,
200		).Scan(&total); err != nil {
201			return nil, 0, unavailable(err)
202		}
203	
204		rows, err := c.QueryContext(ctx,
205			"SELECT id, artifact, version FROM sboms WHERE artifact = ? ORDER BY id ASC LIMIT ? OFFSET ?",
206			artifact, pageSize, (page-1)*pageSize)
207		if err != nil {
208			return nil, 0, unavailable(err)
209		}
210		defer rows.Close()
211	
212		items = []*model.SBOM{}
213		ids := make([]int64, 0, pageSize)
214		indexByID := make(map[int64]int, pageSize)
215		for rows.Next() {
216			sbom := &model.SBOM{Components: []model.Component{}}
217			if err := rows.Scan(&sbom.ID, &sbom.Artifact, &sbom.Version); err != nil {
218				return nil, 0, unavailable(err)
219			}
220			ids = append(ids, sbom.ID)
221			indexByID[sbom.ID] = len(items)
222			items = append(items, sbom)
223		}
224		if err := rows.Err(); err != nil {
225			return nil, 0, unavailable(err)
226		}
227	
228		// Empty page (unknown artifact or a page past the last one): the count was
229		// already read, and the two detail queries must not run with an empty IN
230		// list. Total is still returned to the caller.
231		if len(ids) == 0 {
232			if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
233				return nil, 0, unavailable(err)
234			}
235			committed = true
236			return items, total, nil
237		}
238	
239		if err := loadComponentsInto(ctx, c, items, ids, indexByID); err != nil {
240			return nil, 0, err
241		}
242		if err := loadDependenciesInto(ctx, c, items, ids, indexByID); err != nil {
243			return nil, 0, err
244		}
245	
246		if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
247			return nil, 0, unavailable(err)
248		}
249		committed = true
250		return items, total, nil
251	}
252	
253	// loadComponentsInto reads every component of the given manifests in one
254	// query and attaches the ordered components to their manifests. It is the
255	// single component reconstruction rule of the service: List calls it for the
256	// current page, and Register's idempotency/conflict check calls it (through
257	// loadSBOM) for the one stored manifest, so both read paths rebuild
258	// components exactly the same way.
259	func loadComponentsInto(ctx context.Context, q queryer, items []*model.SBOM, ids []int64, indexByID map[int64]int) error {
260		query := `
261	SELECT c.sbom_id, c.coordinate, c.license
262	FROM components c
263	WHERE c.sbom_id IN (` + placeholders(len(ids)) + `)
264	ORDER BY c.sbom_id ASC, c.coordinate ASC`
265		args := int64Args(ids)
266		rows, err := q.QueryContext(ctx, query, args...)
267		if err != nil {
268			return unavailable(err)
269		}
270		defer rows.Close()
271	
272		for rows.Next() {
273			var sbomID int64
274			var comp model.Component
275			comp.Dependencies = []string{}
276			if err := rows.Scan(&sbomID, &comp.Coordinate, &comp.License); err != nil {
277				return unavailable(err)
278			}
279			items[indexByID[sbomID]].Components = append(items[indexByID[sbomID]].Components, comp)
280		}
281		return rowsError(rows.Err())
282	}
283	
284	// loadDependenciesInto reads every dependency edge of the given manifests in
285	// one query. Both endpoints belong to the same manifest: the JOIN on sbom_id
286	// keeps edges scoped to the given manifests and also prevents a target row
287	// from another version ever matching when coordinates repeat across versions.
288	// Like loadComponentsInto it is shared by List (for a page) and by Register's
289	// idempotency/conflict check (through loadSBOM, for a single manifest).
290	func loadDependenciesInto(ctx context.Context, q queryer, items []*model.SBOM, ids []int64, indexByID map[int64]int) error {
291		query := `
292	SELECT sc.sbom_id, sc.coordinate, tc.coordinate
293	FROM dependencies d
294	JOIN components sc ON sc.id = d.component_id
295	JOIN components tc ON tc.id = d.target_id AND tc.sbom_id = sc.sbom_id
296	WHERE sc.sbom_id IN (` + placeholders(len(ids)) + `)
297	ORDER BY sc.sbom_id ASC, sc.coordinate ASC, tc.coordinate ASC`
298		rows, err := q.QueryContext(ctx, query, int64Args(ids)...)
299		if err != nil {
300			return unavailable(err)
301		}
302		defer rows.Close()
303	
304		// Coordinates are unique within a manifest, so a (sbom ID, coordinate) pair
305		// locates the owning component even when two versions share a coordinate.
306		coordinateIndex := make(map[int64]map[string]int, len(items))
307		for _, sbom := range items {
308			byCoordinate := make(map[string]int, len(sbom.Components))
309			for j := range sbom.Components {
310				byCoordinate[sbom.Components[j].Coordinate] = j
311			}
312			coordinateIndex[sbom.ID] = byCoordinate
313		}
314	
315		for rows.Next() {
316			var sbomID int64
317			var from, to string
318			if err := rows.Scan(&sbomID, &from, &to); err != nil {
319				return unavailable(err)
320			}
321			comp := &items[indexByID[sbomID]].Components[coordinateIndex[sbomID][from]]
322			comp.Dependencies = append(comp.Dependencies, to)
323		}
324		return rowsError(rows.Err())
325	}
326	
327	// rowsError maps a drained cursor's terminal error without wrapping nil.
328	func rowsError(err error) error {
329		if err == nil {
330			return nil
331		}
332		return unavailable(err)
333	}
334	
335	// placeholders builds "?,?,?" for an IN-list of n values.
336	func placeholders(n int) string {
337		return strings.Repeat("?,", n-1) + "?"
338	}
339	
340	func int64Args(ids []int64) []any {
341		args := make([]any, len(ids))
342		for i, id := range ids {
343			args[i] = id
344		}
345		return args
346	}
347	
348	// loadSBOM reconstructs a single stored manifest for Register's
349	// idempotency/conflict check. It reads the manifest row itself, then rebuilds
350	// components and dependencies through the same loaders List applies to a
351	// page, so the registration read path and the paged read path share one
352	// reconstruction rule by construction.
353	func loadSBOM(ctx context.Context, q queryer, id int64) (*model.SBOM, error) {
354		sbom := &model.SBOM{ID: id, Components: []model.Component{}}
355		if err := q.QueryRowContext(ctx,
356			"SELECT artifact, version FROM sboms WHERE id = ?", id,
357		).Scan(&sbom.Artifact, &sbom.Version); err != nil {
358			return nil, unavailable(err)
359		}
360	
361		// A one-manifest page: the shared loaders keep the component and
362		// dependency ordering/scoping rules identical to List's paged reads.
363		items := []*model.SBOM{sbom}
364		ids := []int64{id}
365		indexByID := map[int64]int{id: 0}
366		if err := loadComponentsInto(ctx, q, items, ids, indexByID); err != nil {
367			return nil, err
368		}
369		if err := loadDependenciesInto(ctx, q, items, ids, indexByID); err != nil {
370			return nil, err
371		}
372		return sbom, nil
373	}
374	
375	// equalContent compares normalized manifests (sorted components and
376	// dependencies); artifact and version already matched in SQL.
377	func equalContent(a, b *model.SBOM) bool {
378		if len(a.Components) != len(b.Components) {
379			return false
380		}
381		for i := range a.Components {
382			x, y := &a.Components[i], &b.Components[i]
383			if x.Coordinate != y.Coordinate || x.License != y.License {
384				return false
385			}
386			if len(x.Dependencies) != len(y.Dependencies) {
387				return false
388			}
389			for j := range x.Dependencies {
390				if x.Dependencies[j] != y.Dependencies[j] {
391					return false
392				}
393			}
394		}
395		return true
396	}
397	
398	func countDependencies(in *model.SBOM) int {
399		n := 0
400		for i := range in.Components {
401			n += len(in.Components[i].Dependencies)
402		}
403		return n
404	}
405	
406	func unavailable(err error) error {
407		if errors.Is(err, model.ErrStorageUnavailable) {
408			return err
409		}
410		return fmt.Errorf("%w: %v", model.ErrStorageUnavailable, err)
411	}
412	
413	const schema = `
414	CREATE TABLE IF NOT EXISTS service_metadata (
415	    key   TEXT PRIMARY KEY,
416	    value TEXT NOT NULL
417	);
418	CREATE TABLE IF NOT EXISTS sboms (
419	    id       INTEGER PRIMARY KEY,
420	    artifact TEXT NOT NULL,
421	    version  TEXT NOT NULL,
422	    UNIQUE (artifact, version)
423	);
424	CREATE TABLE IF NOT EXISTS components (
425	    id         INTEGER PRIMARY KEY,
426	    sbom_id    INTEGER NOT NULL REFERENCES sboms(id) ON DELETE CASCADE,
427	    coordinate TEXT NOT NULL,
428	    license    TEXT NOT NULL,
429	    UNIQUE (sbom_id, coordinate)
430	);
431	CREATE TABLE IF NOT EXISTS dependencies (
432	    id           INTEGER PRIMARY KEY,
433	    component_id INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
434	    target_id    INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
435	    UNIQUE (component_id, target_id)
436	);
437	CREATE INDEX IF NOT EXISTS idx_sboms_artifact ON sboms(artifact);
438	`
439

